def bestrelpath(directory: Path, dest: Path) -> str:







    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    # Find the longest common directory.
    base = commonpath(directory, dest)
    # Can be the case on Windows for two absolute paths on different drives.
    # Can be the case for two relative paths without common prefix.
    # Can be the case for a relative path and an absolute path.
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(
        # Back from directory to base.
        *([os.pardir] * len(reldirectory.parts)),
        # Forward from base to dest.
        *reldest.parts,
    )

def move_cursor_backward(self) -> None:

    row, col = self.cursor_position
    if col == 0:
        row -= 1
        col = self.screen_size.col - 1
    else:
        col -= 1
    SetConsoleCursorPosition(
        self._handle, coords=WindowsCoordinates(row=row, col=col)
    )

def move_cursor_forward(self) -> None:

    row, col = self.cursor_position
    if col == self.screen_size.col - 1:
        row += 1
        col = 0
    else:
        col += 1
    SetConsoleCursorPosition(
        self._handle, coords=WindowsCoordinates(row=row, col=col)
    )

def get_level_text(self, record: LogRecord) -> Text:








    level_name = record.levelname
    level_text = Text.styled(
        level_name.ljust(8), f"logging.level.{level_name.lower()}"
    )
    return level_text

def format(self, record: logging.LogRecord) -> str:
    fmt = self._level_to_fmt_mapping.get(record.levelno, self._original_fmt)
    self._style._fmt = fmt
    return super().format(record)

def get_log_level_for_setting(config: Config, *setting_names: str) -> Optional[int]:
    for setting_name in setting_names:
        log_level = config.getoption(setting_name)
        if log_level is None:
            log_level = config.getini(setting_name)
        if log_level:
            break
    else:
        return None

    if isinstance(log_level, str):
        log_level = log_level.upper()
    try:
        return int(getattr(logging, log_level, log_level))
    except ValueError as e:
        # Python logging does not recognise this as a logging level
        raise UsageError(
            f"'{log_level}' is not recognized as a logging level name for "
            f"'{setting_name}'. Please consider passing the "
            "logging level num instead."
        ) from e

@hookimpl(wrapper=True)
def pytest_runtestloop(self, session: Session) -> Generator[None, object, object]:
    if session.config.option.collectonly:
        return (yield)

    if self._log_cli_enabled() and self._config.getoption("verbose") < 1:
        # The verbose flag is needed to avoid messy test progress output.
        self._config.option.verbose = 1

    with catching_logs(self.log_cli_handler, level=self.log_cli_level):
        with catching_logs(self.log_file_handler, level=self.log_file_level):
            return (yield)  # Run all the tests.

def __getattr__(self, name: str) -> MarkDecorator:

    if name[0] == "_":
        raise AttributeError("Marker name must NOT start with underscore")

    if self._config is not None:
        # We store a set of markers as a performance optimisation - if a mark
        # name is in the set we definitely know it, but a mark may be known and
        # not in the set.  We therefore start by updating the set!
        if name not in self._markers:
            for line in self._config.getini("markers"):
                # example lines: "skipif(condition): skip the given test if..."
                # or "hypothesis: tests which use Hypothesis", so to get the
                # marker name we split on both `:` and `(`.
                marker = line.split(":")[0].split("(")[0].strip()
                self._markers.add(marker)

        # If the name is not in the set of known marks after updating,
        # then it really is time to issue a warning or an error.
        if name not in self._markers:
            if self._config.option.strict_markers or self._config.option.strict:
                fail(
                    f"{name!r} not found in `markers` configuration option",
                    pytrace=False,
                )

            # Raise a specific error for common misspellings of "parametrize".
            if name in ["parameterize", "parametrise", "parameterise"]:
                __tracebackhide__ = True
                fail(f"Unknown '{name}' mark, did you mean 'parametrize'?")

            warnings.warn(
                "Unknown pytest.mark.%s - is this a typo?  You can register "
                "custom marks to avoid this warning - for details, see "
                "https://docs.pytest.org/en/stable/how-to/mark.html" % name,
                PytestUnknownMarkWarning,
                2,
            )

    return MarkDecorator(Mark(name, (), {}, _ispytest=True), _ispytest=True)

def pretty_repr(
    _object: Any,
    *,
    max_width: int = 80,
    indent_size: int = 4,
    max_length: Optional[int] = None,
    max_string: Optional[int] = None,
    max_depth: Optional[int] = None,
    expand_all: bool = False,
) -> str:


















    if _safe_isinstance(_object, Node):
        node = _object
    else:
        node = traverse(
            _object, max_length=max_length, max_string=max_string, max_depth=max_depth
        )
    repr_str: str = node.render(
        max_width=max_width, indent_size=indent_size, expand_all=expand_all
    )
    return repr_str

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> "Measurement":
    pretty_str = pretty_repr(
        self._object,
        max_width=options.max_width,
        indent_size=self.indent_size,
        max_length=self.max_length,
        max_string=self.max_string,
        max_depth=self.max_depth,
        expand_all=self.expand_all,
    )
    text_width = (
        max(cell_len(line) for line in pretty_str.splitlines()) if pretty_str else 0
    )
    return Measurement(text_width, text_width)

def divide_line(text: str, width: int, fold: bool = True) -> list[int]:












    break_positions: list[int] = []  # offsets to insert the breaks at
    append = break_positions.append
    cell_offset = 0
    _cell_len = cell_len

    for start, _end, word in words(text):
        word_length = _cell_len(word.rstrip())
        remaining_space = width - cell_offset
        word_fits_remaining_space = remaining_space >= word_length

        if word_fits_remaining_space:
            # Simplest case - the word fits within the remaining width for this line.
            cell_offset += _cell_len(word)
        else:
            # Not enough space remaining for this word on the current line.
            if word_length > width:
                # The word doesn't fit on any line, so we can't simply
                # place it on the next line...
                if fold:
                    # Fold the word across multiple lines.
                    folded_word = chop_cells(word, width=width)
                    for last, line in loop_last(folded_word):
                        if start:
                            append(start)
                        if last:
                            cell_offset = _cell_len(line)
                        else:
                            start += len(line)
                else:
                    # Folding isn't allowed, so crop the word.
                    if start:
                        append(start)
                    cell_offset = _cell_len(word)
            elif cell_offset and start:
                # The word doesn't fit within the remaining space on the current
                # line, but it *can* fit on to the next (empty) line.
                append(start)
                cell_offset = _cell_len(word)

    return break_positions

def __init__(
    self,
    indent: int = 4,
    width: int = 80,
    depth: Optional[int] = None,
) -> None:













    if indent < 0:
        raise ValueError("indent must be >= 0")
    if depth is not None and depth <= 0:
        raise ValueError("depth must be > 0")
    if not width:
        raise ValueError("width must be != 0")
    self._depth = depth
    self._indent_per_level = indent
    self._width = width

def render(
    self, max_width: int = 80, indent_size: int = 4, expand_all: bool = False
) -> str:










    lines = [_Line(node=self, is_root=True)]
    line_no = 0
    while line_no < len(lines):
        line = lines[line_no]
        if line.expandable and not line.expanded:
            if expand_all or not line.check_length(max_width):
                lines[line_no : line_no + 1] = line.expand(indent_size)
        line_no += 1

    repr_str = "\n".join(str(line) for line in lines)
    return repr_str

def __take_sys_modules_snapshot(self) -> SysModulesSnapshot:
    # Some zope modules used by twisted-related tests keep internal state
    # and can't be deleted; we had some trouble in the past with
    # `zope.interface` for example.
    #
    # Preserve readline due to https://bugs.python.org/issue41033.
    # pexpect issues a SIGWINCH.
    def preserve_module(name):
        return name.startswith(("zope", "readline"))

    return SysModulesSnapshot(preserve=preserve_module)

def time_pretty_indent_guides(self):
    pretty = Pretty(snippets.PYTHON_DICT, indent_guides=True)
    self.console.print(pretty)

def visit_Call(self, call: ast.Call) -> Tuple[ast.Name, str]:
    new_func, func_expl = self.visit(call.func)
    arg_expls = []
    new_args = []
    new_kwargs = []
    for arg in call.args:
        if isinstance(arg, ast.Name) and arg.id in self.variables_overwrite.get(
            self.scope, {}
        ):
            arg = self.variables_overwrite[self.scope][arg.id]  # type:ignore[assignment]
        res, expl = self.visit(arg)
        arg_expls.append(expl)
        new_args.append(res)
    for keyword in call.keywords:
        if isinstance(
            keyword.value, ast.Name
        ) and keyword.value.id in self.variables_overwrite.get(self.scope, {}):
            keyword.value = self.variables_overwrite[self.scope][keyword.value.id]  # type:ignore[assignment]
        res, expl = self.visit(keyword.value)
        new_kwargs.append(ast.keyword(keyword.arg, res))
        if keyword.arg:
            arg_expls.append(keyword.arg + "=" + expl)
        else:  # **args have `arg` keywords with an .arg of None
            arg_expls.append("**" + expl)

    expl = "{}({})".format(func_expl, ", ".join(arg_expls))
    new_call = ast.Call(new_func, new_args, new_kwargs)
    res = self.assign(new_call)
    res_expl = self.explanation_param(self.display(res))
    outer_expl = f"{res_expl}\n{{{res_expl} = {expl}\n}}"
    return res, outer_expl

def bestrelpath(directory: Path, dest: Path) -> str:







    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    # Find the longest common directory.
    base = commonpath(directory, dest)
    # Can be the case on Windows for two absolute paths on different drives.
    # Can be the case for two relative paths without common prefix.
    # Can be the case for a relative path and an absolute path.
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(
        # Back from directory to base.
        *([os.pardir] * len(reldirectory.parts)),
        # Forward from base to dest.
        *reldest.parts,
    )

def resume_global_capture(self) -> None:
    # During teardown of the python process, and on rare occasions, capture
    # attributes can be `None` while trying to resume global capture.
    if self._global_capturing is not None:
        self._global_capturing.resume_capturing()

def refresh(self) -> None:

    with self._lock:
        self._live_render.set_renderable(self.renderable)
        if self.console.is_jupyter:  # pragma: no cover
            try:
                from IPython.display import display
                from ipywidgets import Output
            except ImportError:
                import warnings

                warnings.warn('install "ipywidgets" for Jupyter support')
            else:
                if self.ipy_widget is None:
                    self.ipy_widget = Output()
                    display(self.ipy_widget)

                with self.ipy_widget:
                    self.ipy_widget.clear_output(wait=True)
                    self.console.print(self._live_render.renderable)
        elif self.console.is_terminal and not self.console.is_dumb_terminal:
            with self.console:
                self.console.print(Control())
        elif (
            not self._started and not self.transient
        ):  # if it is finished allow files or dumb-terminals to see final result
            with self.console:
                self.console.print(Control())

@classmethod
@lru_cache(maxsize=4096)
def parse(cls, style_definition: str) -> "Style":











    if style_definition.strip() == "none" or not style_definition:
        return cls.null()

    STYLE_ATTRIBUTES = cls.STYLE_ATTRIBUTES
    color: Optional[str] = None
    bgcolor: Optional[str] = None
    attributes: Dict[str, Optional[Any]] = {}
    link: Optional[str] = None

    words = iter(style_definition.split())
    for original_word in words:
        word = original_word.lower()
        if word == "on":
            word = next(words, "")
            if not word:
                raise errors.StyleSyntaxError("color expected after 'on'")
            try:
                Color.parse(word) is None
            except ColorParseError as error:
                raise errors.StyleSyntaxError(
                    f"unable to parse {word!r} as background color; {error}"
                ) from None
            bgcolor = word

        elif word == "not":
            word = next(words, "")
            attribute = STYLE_ATTRIBUTES.get(word)
            if attribute is None:
                raise errors.StyleSyntaxError(
                    f"expected style attribute after 'not', found {word!r}"
                )
            attributes[attribute] = False

        elif word == "link":
            word = next(words, "")
            if not word:
                raise errors.StyleSyntaxError("URL expected after 'link'")
            link = word

        elif word in STYLE_ATTRIBUTES:
            attributes[STYLE_ATTRIBUTES[word]] = True

        else:
            try:
                Color.parse(word)
            except ColorParseError as error:
                raise errors.StyleSyntaxError(
                    f"unable to parse {word!r} as color; {error}"
                ) from None
            color = word
    style = Style(color=color, bgcolor=bgcolor, link=link, **attributes)
    return style

@property
def tolerance(self):






    def set_default(x, default):
        return x if x is not None else default

    # Figure out what the absolute tolerance should be.  ``self.abs`` is
    # either None or a value specified by the user.
    absolute_tolerance = set_default(self.abs, self.DEFAULT_ABSOLUTE_TOLERANCE)

    if absolute_tolerance < 0:
        raise ValueError(
            f"absolute tolerance can't be negative: {absolute_tolerance}"
        )
    if math.isnan(absolute_tolerance):
        raise ValueError("absolute tolerance can't be NaN.")

    # If the user specified an absolute tolerance but not a relative one,
    # just return the absolute tolerance.
    if self.rel is None:
        if self.abs is not None:
            return absolute_tolerance

    # Figure out what the relative tolerance should be.  ``self.rel`` is
    # either None or a value specified by the user.  This is done after
    # we've made sure the user didn't ask for an absolute tolerance only,
    # because we don't want to raise errors about the relative tolerance if
    # we aren't even going to use it.
    relative_tolerance = set_default(
        self.rel, self.DEFAULT_RELATIVE_TOLERANCE
    ) * abs(self.expected)

    if relative_tolerance < 0:
        raise ValueError(
            f"relative tolerance can't be negative: {relative_tolerance}"
        )
    if math.isnan(relative_tolerance):
        raise ValueError("relative tolerance can't be NaN.")

    # Return the larger of the relative and absolute tolerances.
    return max(relative_tolerance, absolute_tolerance)

def move(self, target):

    if target.relto(self):
        raise error.EINVAL(target, "cannot move path into a subdirectory of itself")
    try:
        self.rename(target)
    except error.EXDEV:  # invalid cross-device link
        self.copy(target)
        self.remove()

@property
def result(self) -> TResult:




    if self.excinfo is not None:
        raise AttributeError(f"{self!r} has no valid result")
    # The cast is safe because an exception wasn't raised, hence
    # _result has the expected function return type (which may be
    #  None, that's why a cast and not an assert).
    return cast(TResult, self._result)

def parse_args(  # type: ignore
    self,
    args: Optional[Sequence[str]] = None,
    namespace: Optional[argparse.Namespace] = None,
) -> argparse.Namespace:

    parsed, unrecognized = self.parse_known_args(args, namespace)
    if unrecognized:
        for arg in unrecognized:
            if arg and arg[0] == "-":
                lines = ["unrecognized arguments: %s" % (" ".join(unrecognized))]
                for k, v in sorted(self.extra_info.items()):
                    lines.append(f"  {k}: {v}")
                self.error("\n".join(lines))
        getattr(parsed, FILE_OR_DIR).extend(unrecognized)
    return parsed

@property
def is_terminal(self) -> bool:






    if self._force_terminal is not None:
        return self._force_terminal

    if hasattr(sys.stdin, "__module__") and sys.stdin.__module__.startswith(
        "idlelib"
    ):
        # Return False for Idle which claims to be a tty but can't handle ansi codes
        return False

    if self.is_jupyter:
        # return False for Jupyter, which may have FORCE_COLOR set
        return False

    # If FORCE_COLOR env var has any value at all, we assume a terminal.
    force_color = self._environ.get("FORCE_COLOR")
    if force_color is not None:
        self._force_terminal = True
        return True

    isatty: Optional[Callable[[], bool]] = getattr(self.file, "isatty", None)
    try:
        return False if isatty is None else isatty()
    except ValueError:
        # in some situation (at the end of a pytest run for example) isatty() can raise
        # ValueError: I/O operation on closed file
        # return False because we aren't in a terminal anymore
        return False

def legacy_windows_render(buffer: Iterable[Segment], term: LegacyWindowsTerm) -> None:






    for text, style, control in buffer:
        if not control:
            if style:
                term.write_styled(text, style)
            else:
                term.write_text(text)
        else:
            control_codes: Sequence[ControlCode] = control
            for control_code in control_codes:
                control_type = control_code[0]
                if control_type == ControlType.CURSOR_MOVE_TO:
                    _, x, y = cast(Tuple[ControlType, int, int], control_code)
                    term.move_cursor_to(WindowsCoordinates(row=y - 1, col=x - 1))
                elif control_type == ControlType.CARRIAGE_RETURN:
                    term.write_text("\r")
                elif control_type == ControlType.HOME:
                    term.move_cursor_to(WindowsCoordinates(0, 0))
                elif control_type == ControlType.CURSOR_UP:
                    term.move_cursor_up()
                elif control_type == ControlType.CURSOR_DOWN:
                    term.move_cursor_down()
                elif control_type == ControlType.CURSOR_FORWARD:
                    term.move_cursor_forward()
                elif control_type == ControlType.CURSOR_BACKWARD:
                    term.move_cursor_backward()
                elif control_type == ControlType.CURSOR_MOVE_TO_COLUMN:
                    _, column = cast(Tuple[ControlType, int], control_code)
                    term.move_cursor_to_column(column - 1)
                elif control_type == ControlType.HIDE_CURSOR:
                    term.hide_cursor()
                elif control_type == ControlType.SHOW_CURSOR:
                    term.show_cursor()
                elif control_type == ControlType.ERASE_IN_LINE:
                    _, mode = cast(Tuple[ControlType, int], control_code)
                    if mode == 0:
                        term.erase_end_of_line()
                    elif mode == 1:
                        term.erase_start_of_line()
                    elif mode == 2:
                        term.erase_line()
                elif control_type == ControlType.SET_WINDOW_TITLE:
                    _, title = cast(Tuple[ControlType, str], control_code)
                    term.set_title(title)

def highlight(
    self,
    code: str,
    line_range: Optional[Tuple[Optional[int], Optional[int]]] = None,
) -> Text:










    base_style = self._get_base_style()
    justify: JustifyMethod = (
        "default" if base_style.transparent_background else "left"
    )

    text = Text(
        justify=justify,
        style=base_style,
        tab_size=self.tab_size,
        no_wrap=not self.word_wrap,
    )
    _get_theme_style = self._theme.get_style_for_token

    lexer = self.lexer or self.default_lexer

    if lexer is None:
        text.append(code)
    else:
        if line_range:
            # More complicated path to only stylize a portion of the code
            # This speeds up further operations as there are less spans to process
            line_start, line_end = line_range

            def line_tokenize() -> Iterable[Tuple[Any, str]]:

                assert lexer  # required to make MyPy happy - we know lexer is not None at this point

                for token_type, token in lexer.get_tokens(code):
                    while token:
                        line_token, new_line, token = token.partition("\n")
                        yield token_type, line_token + new_line

            def tokens_to_spans() -> Iterable[Tuple[str, Optional[Style]]]:

                tokens = iter(line_tokenize())
                line_no = 0
                _line_start = line_start - 1 if line_start else 0

                # Skip over tokens until line start
                while line_no < _line_start:
                    try:
                        _token_type, token = next(tokens)
                    except StopIteration:
                        break
                    yield (token, None)
                    if token.endswith("\n"):
                        line_no += 1
                # Generate spans until line end
                for token_type, token in tokens:
                    yield (token, _get_theme_style(token_type))
                    if token.endswith("\n"):
                        line_no += 1
                        if line_end and line_no >= line_end:
                            break

            text.append_tokens(tokens_to_spans())

        else:
            text.append_tokens(
                (token, _get_theme_style(token_type))
                for token_type, token in lexer.get_tokens(code)
            )
        if self.background_color is not None:
            text.stylize(f"on {self.background_color}")

    if self._stylized_ranges:
        self._apply_stylized_ranges(text)

    return text

def getstatementrange_ast(
    lineno: int,
    source: Source,
    assertion: bool = False,
    astnode: Optional[ast.AST] = None,
) -> Tuple[ast.AST, int, int]:
    if astnode is None:
        content = str(source)
        # See #4260:
        # Don't produce duplicate warnings when compiling source to find AST.
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            astnode = ast.parse(content, "source", "exec")

    start, end = get_statement_startend2(lineno, astnode)
    # We need to correct the end:
    # - ast-parsing strips comments
    # - there might be empty lines
    # - we might have lesser indented code blocks at the end
    if end is None:
        end = len(source.lines)

    if end > start + 1:
        # Make sure we don't span differently indented code blocks
        # by using the BlockFinder helper used which inspect.getsource() uses itself.
        block_finder = inspect.BlockFinder()
        # If we start with an indented line, put blockfinder to "started" mode.
        block_finder.started = (
            bool(source.lines[start]) and source.lines[start][0].isspace()
        )
        it = ((x + "\n") for x in source.lines[start:end])
        try:
            for tok in tokenize.generate_tokens(lambda: next(it)):
                block_finder.tokeneater(*tok)
        except (inspect.EndOfBlock, IndentationError):
            end = block_finder.last + start
        except Exception:
            pass

    # The end might still point to a comment or empty line, correct it.
    while end:
        line = source.lines[end - 1].lstrip()
        if line.startswith("#") or not line:
            end -= 1
        else:
            break
    return astnode, start, end

def stylize_range(
    self, style: StyleType, start: SyntaxPosition, end: SyntaxPosition
) -> None:









    self._stylized_ranges.append(_SyntaxHighlightRange(style, start, end))

def get_source(
    self,
    source: Optional["Source"],
    line_index: int = -1,
    excinfo: Optional[ExceptionInfo[BaseException]] = None,
    short: bool = False,
) -> List[str]:

    lines = []
    if source is not None and line_index < 0:
        line_index += len(source)
    if source is None or line_index >= len(source.lines) or line_index < 0:
        # `line_index` could still be outside `range(len(source.lines))` if
        # we're processing AST with pathological position attributes.
        source = Source("???")
        line_index = 0
    space_prefix = "    "
    if short:
        lines.append(space_prefix + source.lines[line_index].strip())
    else:
        for line in source.lines[:line_index]:
            lines.append(space_prefix + line)
        lines.append(self.flow_marker + "   " + source.lines[line_index])
        for line in source.lines[line_index + 1 :]:
            lines.append(space_prefix + line)
    if excinfo is not None:
        indent = 4 if short else self._getindent(source)
        lines.extend(self.get_exconly(excinfo, indent=indent, markall=True))
    return lines

def source(self) -> "Source":

    # return source only for that part of code
    return Source(self.raw)

def __rich_console__(
    self, console: Console, options: ConsoleOptions
) -> RenderResult:
    segments = Segments(self._get_syntax(console, options))
    if self.padding:
        yield Padding(
            segments, style=self._theme.get_background_style(), pad=self.padding
        )
    else:
        yield segments

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    if self.new_lines:
        line = Segment.line()
        for segment in self.segments:
            yield segment
            yield line
    else:
        yield from self.segments

def display(segments: Iterable[Segment], text: str) -> None:

    html = _render_segments(segments)
    jupyter_renderable = JupyterRenderable(html, text)
    try:
        from IPython.display import display as ipython_display

        ipython_display(jupyter_renderable)
    except ModuleNotFoundError:
        # Handle the case where the Console has force_jupyter=True,
        # but IPython is not installed.
        pass

@classmethod
def apply_style(
    cls,
    segments: Iterable["Segment"],
    style: Optional[Style] = None,
    post_style: Optional[Style] = None,
) -> Iterable["Segment"]:












    result_segments = segments
    if style:
        apply = style.__add__
        result_segments = (
            cls(text, None if control else apply(_style), control)
            for text, _style, control in result_segments
        )
    if post_style:
        result_segments = (
            cls(
                text,
                (
                    None
                    if control
                    else (_style + post_style if _style else post_style)
                ),
                control,
            )
            for text, _style, control in result_segments
        )
    return result_segments

def render(
    self,
    text: str = "",
    *,
    color_system: Optional[ColorSystem] = ColorSystem.TRUECOLOR,
    legacy_windows: bool = False,
) -> str:









    if not text or color_system is None:
        return text
    attrs = self._ansi or self._make_ansi_codes(color_system)
    rendered = f"\x1b[{attrs}m{text}\x1b[0m" if attrs else text
    if self._link and not legacy_windows:
        rendered = (
            f"\x1b]8;id={self._link_id};{self._link}\x1b\\{rendered}\x1b]8;;\x1b\\"
        )
    return rendered

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    align = self.align
    width = console.measure(self.renderable, options=options).maximum
    rendered = console.render(
        Constrain(
            self.renderable, width if self.width is None else min(width, self.width)
        ),
        options.update(height=None),
    )
    lines = list(Segment.split_lines(rendered))
    width, height = Segment.get_shape(lines)
    lines = Segment.set_shape(lines, width, height)
    new_line = Segment.line()
    excess_space = options.max_width - width
    style = console.get_style(self.style) if self.style is not None else None

    def generate_segments() -> Iterable[Segment]:
        if excess_space <= 0:
            # Exact fit
            for line in lines:
                yield from line
                yield new_line

        elif align == "left":
            # Pad on the right
            pad = Segment(" " * excess_space, style) if self.pad else None
            for line in lines:
                yield from line
                if pad:
                    yield pad
                yield new_line

        elif align == "center":
            # Pad left and right
            left = excess_space // 2
            pad = Segment(" " * left, style)
            pad_right = (
                Segment(" " * (excess_space - left), style) if self.pad else None
            )
            for line in lines:
                if left:
                    yield pad
                yield from line
                if pad_right:
                    yield pad_right
                yield new_line

        elif align == "right":
            # Padding on left
            pad = Segment(" " * excess_space, style)
            for line in lines:
                yield pad
                yield from line
                yield new_line

    blank_line = (
        Segment(f"{' ' * (self.width or options.max_width)}\n", style)
        if self.pad
        else Segment("\n")
    )

    def blank_lines(count: int) -> Iterable[Segment]:
        if count > 0:
            for _ in range(count):
                yield blank_line

    vertical_height = self.height or options.height
    iter_segments: Iterable[Segment]
    if self.vertical and vertical_height is not None:
        if self.vertical == "top":
            bottom_space = vertical_height - height
            iter_segments = chain(generate_segments(), blank_lines(bottom_space))
        elif self.vertical == "middle":
            top_space = (vertical_height - height) // 2
            bottom_space = vertical_height - top_space - height
            iter_segments = chain(
                blank_lines(top_space),
                generate_segments(),
                blank_lines(bottom_space),
            )
        else:  #  self.vertical == "bottom":
            top_space = vertical_height - height
            iter_segments = chain(blank_lines(top_space), generate_segments())
    else:
        iter_segments = generate_segments()
    if self.style:
        style = console.get_style(self.style)
        iter_segments = Segment.apply_style(iter_segments, style)
    yield from iter_segments

def split(
    self,
    separator: str = "\n",
    *,
    include_separator: bool = False,
    allow_blank: bool = False,
) -> Lines:










    assert separator, "separator must not be empty"

    text = self.plain
    if separator not in text:
        return Lines([self.copy()])

    if include_separator:
        lines = self.divide(
            match.end() for match in re.finditer(re.escape(separator), text)
        )
    else:

        def flatten_spans() -> Iterable[int]:
            for match in re.finditer(re.escape(separator), text):
                start, end = match.span()
                yield start
                yield end

        lines = Lines(
            line for line in self.divide(flatten_spans()) if line.plain != separator
        )

    if not allow_blank and text.endswith(separator):
        lines.pop()

    return lines

@classmethod
def split_lines(cls, segments: Iterable["Segment"]) -> Iterable[List["Segment"]]:








    line: List[Segment] = []
    append = line.append

    for segment in segments:
        if "\n" in segment.text and not segment.control:
            text, style, _ = segment
            while text:
                _text, new_line, text = text.partition("\n")
                if _text:
                    append(cls(_text, style))
                if new_line:
                    yield line
                    line = []
                    append = line.append
        else:
            append(segment)
    if line:
        yield line

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> Measurement:
    text = self.plain
    lines = text.splitlines()
    max_text_width = max(cell_len(line) for line in lines) if lines else 0
    words = text.split()
    min_text_width = (
        max(cell_len(word) for word in words) if words else max_text_width
    )
    return Measurement(min_text_width, max_text_width)

def __rich_console__(
    self, console: "Console", options: "ConsoleOptions"
) -> "RenderResult":
    style = console.get_style(self.style) if self.style is not None else None
    lines = console.render_lines(
        self.renderable, options.update(height=None), pad=False
    )
    width, _height = Segment.get_shape(lines)
    new_line = Segment.line()
    height = options.height or options.size.height
    top_space = (height - len(lines)) // 2
    bottom_space = height - top_space - len(lines)
    blank_line = Segment(f"{' ' * width}", style)

    def blank_lines(count: int) -> Iterable[Segment]:
        for _ in range(count):
            yield blank_line
            yield new_line

    if top_space > 0:
        yield from blank_lines(top_space)
    for line in lines:
        yield from line
        yield new_line
    if bottom_space > 0:
        yield from blank_lines(bottom_space)

def resume_global_capture(self) -> None:
    # During teardown of the python process, and on rare occasions, capture
    # attributes can be `None` while trying to resume global capture.
    if self._global_capturing is not None:
        self._global_capturing.resume_capturing()

@classmethod
def split_and_crop_lines(
    cls,
    segments: Iterable["Segment"],
    length: int,
    style: Optional[Style] = None,
    pad: bool = True,
    include_new_lines: bool = True,
) -> Iterable[List["Segment"]]:












    line: List[Segment] = []
    append = line.append

    adjust_line_length = cls.adjust_line_length
    new_line_segment = cls("\n")

    for segment in segments:
        if "\n" in segment.text and not segment.control:
            text, segment_style, _ = segment
            while text:
                _text, new_line, text = text.partition("\n")
                if _text:
                    append(cls(_text, segment_style))
                if new_line:
                    cropped_line = adjust_line_length(
                        line, length, style=style, pad=pad
                    )
                    if include_new_lines:
                        cropped_line.append(new_line_segment)
                    yield cropped_line
                    line.clear()
        else:
            append(segment)
    if line:
        yield adjust_line_length(line, length, style=style, pad=pad)

def write(self, text: str) -> int:
    if not isinstance(text, str):
        raise TypeError(f"write() argument must be str, not {type(text).__name__}")
    buffer = self.__buffer
    lines: List[str] = []
    while text:
        line, new_line, text = text.partition("\n")
        if new_line:
            lines.append("".join(buffer) + line)
            buffer.clear()
        else:
            buffer.append(line)
            break
    if lines:
        console = self.__console
        with console:
            output = Text("\n").join(
                self.__ansi_decoder.decode_line(line) for line in lines
            )
            console.print(output)
    return len(text)

@property
def tolerance(self):






    def set_default(x, default):
        return x if x is not None else default

    # Figure out what the absolute tolerance should be.  ``self.abs`` is
    # either None or a value specified by the user.
    absolute_tolerance = set_default(self.abs, self.DEFAULT_ABSOLUTE_TOLERANCE)

    if absolute_tolerance < 0:
        raise ValueError(
            f"absolute tolerance can't be negative: {absolute_tolerance}"
        )
    if math.isnan(absolute_tolerance):
        raise ValueError("absolute tolerance can't be NaN.")

    # If the user specified an absolute tolerance but not a relative one,
    # just return the absolute tolerance.
    if self.rel is None:
        if self.abs is not None:
            return absolute_tolerance

    # Figure out what the relative tolerance should be.  ``self.rel`` is
    # either None or a value specified by the user.  This is done after
    # we've made sure the user didn't ask for an absolute tolerance only,
    # because we don't want to raise errors about the relative tolerance if
    # we aren't even going to use it.
    relative_tolerance = set_default(
        self.rel, self.DEFAULT_RELATIVE_TOLERANCE
    ) * abs(self.expected)

    if relative_tolerance < 0:
        raise ValueError(
            f"relative tolerance can't be negative: {relative_tolerance}"
        )
    if math.isnan(relative_tolerance):
        raise ValueError("relative tolerance can't be NaN.")

    # Return the larger of the relative and absolute tolerances.
    return max(relative_tolerance, absolute_tolerance)

