def bestrelpath(directory: Path, dest: Path) -> str:







    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    # Find the longest common directory.
    base = commonpath(directory, dest)
    # Can be the case on Windows for two absolute paths on different drives.
    # Can be the case for two relative paths without common prefix.
    # Can be the case for a relative path and an absolute path.
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(
        # Back from directory to base.
        *([os.pardir] * len(reldirectory.parts)),
        # Forward from base to dest.
        *reldest.parts,
    )

def __getattr__(self, name: str) -> MarkDecorator:

    if name[0] == "_":
        raise AttributeError("Marker name must NOT start with underscore")

    if self._config is not None:
        # We store a set of markers as a performance optimisation - if a mark
        # name is in the set we definitely know it, but a mark may be known and
        # not in the set.  We therefore start by updating the set!
        if name not in self._markers:
            for line in self._config.getini("markers"):
                # example lines: "skipif(condition): skip the given test if..."
                # or "hypothesis: tests which use Hypothesis", so to get the
                # marker name we split on both `:` and `(`.
                marker = line.split(":")[0].split("(")[0].strip()
                self._markers.add(marker)

        # If the name is not in the set of known marks after updating,
        # then it really is time to issue a warning or an error.
        if name not in self._markers:
            if self._config.option.strict_markers or self._config.option.strict:
                fail(
                    f"{name!r} not found in `markers` configuration option",
                    pytrace=False,
                )

            # Raise a specific error for common misspellings of "parametrize".
            if name in ["parameterize", "parametrise", "parameterise"]:
                __tracebackhide__ = True
                fail(f"Unknown '{name}' mark, did you mean 'parametrize'?")

            warnings.warn(
                "Unknown pytest.mark.%s - is this a typo?  You can register "
                "custom marks to avoid this warning - for details, see "
                "https://docs.pytest.org/en/stable/how-to/mark.html" % name,
                PytestUnknownMarkWarning,
                2,
            )

    return MarkDecorator(Mark(name, (), {}, _ispytest=True), _ispytest=True)

def assertrepr_compare(
    config, op: str, left: Any, right: Any, use_ascii: bool = False
) -> Optional[List[str]]:

    verbose = config.get_verbosity(Config.VERBOSITY_ASSERTIONS)

    # Strings which normalize equal are often hard to distinguish when printed; use ascii() to make this easier.
    # See issue #3246.
    use_ascii = (
        isinstance(left, str)
        and isinstance(right, str)
        and normalize("NFD", left) == normalize("NFD", right)
    )

    if verbose > 1:
        left_repr = saferepr_unlimited(left, use_ascii=use_ascii)
        right_repr = saferepr_unlimited(right, use_ascii=use_ascii)
    else:
        # XXX: "15 chars indentation" is wrong
        #      ("E       AssertionError: assert "); should use term width.
        maxsize = (
            80 - 15 - len(op) - 2
        ) // 2  # 15 chars indentation, 1 space around op

        left_repr = saferepr(left, maxsize=maxsize, use_ascii=use_ascii)
        right_repr = saferepr(right, maxsize=maxsize, use_ascii=use_ascii)

    summary = f"{left_repr} {op} {right_repr}"
    highlighter = config.get_terminal_writer()._highlight

    explanation = None
    try:
        if op == "==":
            explanation = _compare_eq_any(left, right, highlighter, verbose)
        elif op == "not in":
            if istext(left) and istext(right):
                explanation = _notin_text(left, right, verbose)
        elif op == "!=":
            if isset(left) and isset(right):
                explanation = ["Both sets are equal"]
        elif op == ">=":
            if isset(left) and isset(right):
                explanation = _compare_gte_set(left, right, highlighter, verbose)
        elif op == "<=":
            if isset(left) and isset(right):
                explanation = _compare_lte_set(left, right, highlighter, verbose)
        elif op == ">":
            if isset(left) and isset(right):
                explanation = _compare_gt_set(left, right, highlighter, verbose)
        elif op == "<":
            if isset(left) and isset(right):
                explanation = _compare_lt_set(left, right, highlighter, verbose)

    except outcomes.Exit:
        raise
    except Exception:
        explanation = [
            "(pytest_assertion plugin: representation of details failed: {}.".format(
                _pytest._code.ExceptionInfo.from_current()._getreprcrash()
            ),
            " Probably an object has a faulty __repr__.)",
        ]

    if not explanation:
        return None

    if explanation[0] != "":
        explanation = ["", *explanation]
    return [summary, *explanation]

