def __init__(
    self,
    title: Union[str, Text] = "",
    *,
    characters: str = "─",
    style: Union[str, Style] = "rule.line",
    end: str = "\n",
    align: AlignMethod = "center",
) -> None:
    if cell_len(characters) < 1:
        raise ValueError(
            "'characters' argument must have a cell width of at least 1"
        )
    if align not in ("left", "center", "right"):
        raise ValueError(
            f'invalid value for align, expected "left", "center", "right" (not {align!r})'
        )
    self.title = title
    self.characters = characters
    self.style = style
    self.end = end
    self.align = align

def bestrelpath(directory: Path, dest: Path) -> str:







    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    # Find the longest common directory.
    base = commonpath(directory, dest)
    # Can be the case on Windows for two absolute paths on different drives.
    # Can be the case for two relative paths without common prefix.
    # Can be the case for a relative path and an absolute path.
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(
        # Back from directory to base.
        *([os.pardir] * len(reldirectory.parts)),
        # Forward from base to dest.
        *reldest.parts,
    )

def module_name_from_path(path: Path, root: Path) -> str:






    path = path.with_suffix("")
    try:
        relative_path = path.relative_to(root)
    except ValueError:
        # If we can't get a relative path to root, use the full path, except
        # for the first part ("d:\\" or "/" depending on the platform, for example).
        path_parts = path.parts[1:]
    else:
        # Use the parts for the relative path to the root path.
        path_parts = relative_path.parts

    # Module name for packages do not contain the __init__ file, unless
    # the `__init__.py` file is at the root.
    if len(path_parts) >= 2 and path_parts[-1] == "__init__":
        path_parts = path_parts[:-1]

    # Module names cannot contain ".", normalize them to "_". This prevents
    # a directory having a "." in the name (".env.310" for example) causing extra intermediate modules.
    # Also, important to replace "." at the start of paths, as those are considered relative imports.
    path_parts = tuple(x.replace(".", "_") for x in path_parts)

    return ".".join(path_parts)

def try_cleanup(path: Path, consider_lock_dead_if_created_before: float) -> None:

    if ensure_deletable(path, consider_lock_dead_if_created_before):
        maybe_delete_a_numbered_dir(path)

@property
def tolerance(self):






    def set_default(x, default):
        return x if x is not None else default

    # Figure out what the absolute tolerance should be.  ``self.abs`` is
    # either None or a value specified by the user.
    absolute_tolerance = set_default(self.abs, self.DEFAULT_ABSOLUTE_TOLERANCE)

    if absolute_tolerance < 0:
        raise ValueError(
            f"absolute tolerance can't be negative: {absolute_tolerance}"
        )
    if math.isnan(absolute_tolerance):
        raise ValueError("absolute tolerance can't be NaN.")

    # If the user specified an absolute tolerance but not a relative one,
    # just return the absolute tolerance.
    if self.rel is None:
        if self.abs is not None:
            return absolute_tolerance

    # Figure out what the relative tolerance should be.  ``self.rel`` is
    # either None or a value specified by the user.  This is done after
    # we've made sure the user didn't ask for an absolute tolerance only,
    # because we don't want to raise errors about the relative tolerance if
    # we aren't even going to use it.
    relative_tolerance = set_default(
        self.rel, self.DEFAULT_RELATIVE_TOLERANCE
    ) * abs(self.expected)

    if relative_tolerance < 0:
        raise ValueError(
            f"relative tolerance can't be negative: {relative_tolerance}"
        )
    if math.isnan(relative_tolerance):
        raise ValueError("relative tolerance can't be NaN.")

    # Return the larger of the relative and absolute tolerances.
    return max(relative_tolerance, absolute_tolerance)

def mktemp(self, basename: str, numbered: bool = True) -> Path:














    basename = self._ensure_relative_to_basetemp(basename)
    if not numbered:
        p = self.getbasetemp().joinpath(basename)
        p.mkdir(mode=0o700)
    else:
        p = make_numbered_dir(root=self.getbasetemp(), prefix=basename, mode=0o700)
        self._trace("mktemp", p)
    return p

def pick_unit_and_suffix(size: int, suffixes: List[str], base: int) -> Tuple[int, str]:

    for i, suffix in enumerate(suffixes):
        unit = base**i
        if size < unit * base:
            break
    return unit, suffix

def pytest_sessionfinish(session, exitstatus: Union[int, ExitCode]):



    tmp_path_factory: TempPathFactory = session.config._tmp_path_factory
    basetemp = tmp_path_factory._basetemp
    if basetemp is None:
        return

    policy = tmp_path_factory._retention_policy
    if (
        exitstatus == 0
        and policy == "failed"
        and tmp_path_factory._given_basetemp is None
    ):
        if basetemp.is_dir():
            # We do a "best effort" to remove files, but it might not be possible due to some leaked resource,
            # permissions, etc, in which case we ignore it.
            rmtree(basetemp, ignore_errors=True)

    # Remove dead symlinks.
    if basetemp.is_dir():
        cleanup_dead_symlinks(basetemp)

@pytest.mark.filterwarnings("default::pytest.PytestCollectionWarning")
def test_dont_collect_non_function_callable(pytester: Pytester) -> None:





    pytester.makepyfile(
        """
        class Oh(object):
            def __call__(self):
                pass

        test_a = Oh()

        def test_real():
            pass
    """
    )
    result = pytester.runpytest()
    result.stdout.fnmatch_lines(
        [
            "*collected 1 item*",
            "*test_dont_collect_non_function_callable.py:2: *cannot collect 'test_a' because it is not a function*",
            "*1 passed, 1 warning in *",
        ]
    )

@property
def is_terminal(self) -> bool:






    if self._force_terminal is not None:
        return self._force_terminal

    if hasattr(sys.stdin, "__module__") and sys.stdin.__module__.startswith(
        "idlelib"
    ):
        # Return False for Idle which claims to be a tty but can't handle ansi codes
        return False

    if self.is_jupyter:
        # return False for Jupyter, which may have FORCE_COLOR set
        return False

    # If FORCE_COLOR env var has any value at all, we assume a terminal.
    force_color = self._environ.get("FORCE_COLOR")
    if force_color is not None:
        self._force_terminal = True
        return True

    isatty: Optional[Callable[[], bool]] = getattr(self.file, "isatty", None)
    try:
        return False if isatty is None else isatty()
    except ValueError:
        # in some situation (at the end of a pytest run for example) isatty() can raise
        # ValueError: I/O operation on closed file
        # return False because we aren't in a terminal anymore
        return False

@hookimpl
def pytest_configure(config: Config) -> None:

    if config.pluginmanager.has_plugin("tmpdir"):
        mp = MonkeyPatch()
        config.add_cleanup(mp.undo)
        # Create TmpdirFactory and attach it to the config object.
        #
        # This is to comply with existing plugins which expect the handler to be
        # available at pytest_configure time, but ideally should be moved entirely
        # to the tmpdir_factory session fixture.
        try:
            tmp_path_factory = config._tmp_path_factory  # type: ignore[attr-defined]
        except AttributeError:
            # tmpdir plugin is blocked.
            pass
        else:
            _tmpdirhandler = TempdirFactory(tmp_path_factory, _ispytest=True)
            mp.setattr(config, "_tmpdirhandler", _tmpdirhandler, raising=False)

        config.pluginmanager.register(LegacyTmpdirPlugin, "legacypath-tmpdir")

def pytest_pycollect_makeitem(
    collector: Union[Module, Class], name: str, obj: object
) -> Optional["UnitTestCase"]:
    # Has unittest been imported and is obj a subclass of its TestCase?
    try:
        ut = sys.modules["unittest"]
        # Type ignored because `ut` is an opaque module.
        if not issubclass(obj, ut.TestCase):  # type: ignore
            return None
    except Exception:
        return None
    # Yes, so let's collect it.
    return UnitTestCase.from_parent(collector, name=name, obj=obj)

